    supported=set()
    for row in inputs.get('source_output',{}).get('statements',[]):
        if row['term'][0]=='source_program_scope_supported':
            for uid in row['support_ids']:
                supported.add(uid)
    anchors=[]
    for answer in inputs.get('semantic_answers',[]):
