def any_phrase(t, xs):
    for x in xs:
        if x in t:
            return True
    return False

def add_statement(out, term, support_ids):
    support = unique(support_ids)
    for row in out:
        if row.get('term') == term:
            return
    out.append({'term': term, 'support_ids': support})

def add_once(xs, x):
    if x not in xs:
        xs.append(x)

def make_union(items):
    if not items:
        return None
    value = items[len(items) - 1]
    i = len(items) - 2
    while i >= 0:
        value = ['participant_union', items[i], value]
        i -= 1
    return value

def make_condition(t):
    cs = []
    if 'need to know' in t or 'need-to-know' in t or 'need-to know' in t:
        cs.append(['need_to_know', 'stated purpose'])
    if any_phrase(t, ['bound by obligations of confidentiality', 'treat the confidential information as confidential', 'obliged by their contracts', 'obligated to protect', 'terms and conditions no less protective']):
        cs.append(['confidentiality_bound', 'source-stated confidentiality obligation'])
    if any_phrase(t, ['only to the extent necessary', 'disclosure is necessary', 'as deemed necessary', 'reasonably necessary']):
        cs.append(['extent_necessary', 'source-stated purpose'])
    if not cs:
        return ['no_condition']
    v = cs[0]
    i = 1
    while i < len(cs):
        v = ['and_condition', v, cs[i]]
        i += 1
    return v

def permission_segment(t):
    marks = ['may disclose', 'may share', 'internally share', 'restrict access', 'except in confidence', 'except to such']
    best = -1
    for m in marks:
        p = t.rfind(m)
        if p > best:
            best = p
    if best < 0 and 'not to disclose' in t and (' except ' in t):
        best = t.rfind(' except ')
    return t[best:] if best >= 0 else t

def recipient_terms(t):
    owner = ['receiving_party']
    if any_phrase(t, ["affiliates' officers", 'affiliates’ officers', "affiliate's officers", 'affiliate’s officers']):
        owner = ['affiliates_of', ['receiving_party']]
    xs = []
    if has_word(t, '\\bemployees?\\b'):
        xs.append(['employees_of', owner])
    if has_word(t, '\\bdirectors?\\b'):
        xs.append(['directors_of', owner])
    if has_word(t, '\\bofficers?\\b'):
        xs.append(['officers_of', owner])
    if any_phrase(t, ['legal advisors', 'legal advisers', 'attorneys', 'legal counsel']):
        xs.append(['legal_advisors_of', owner])
    if any_phrase(t, ['financial advisors', 'financial advisers']):
        xs.append(['financial_advisors_of', owner])
    if any_phrase(t, ['professional advisors', 'professional advisers']):
        xs.append(['professional_advisors_of', owner])
    if has_word(t, '\\baccountants?\\b'):
        xs.append(['accountants_of', owner])
    if has_word(t, '\\bconsultants?\\b'):
        xs.append(['consultants_of', owner])
    if has_word(t, '\\bagents?\\b'):
        xs.append(['agents_of', owner])
    if has_word(t, '\\bcontractors?\\b'):
        xs.append(['independent_contractors_of', owner])
    if has_word(t, '\\blenders?\\b'):
        xs.append(['lenders_of', owner])
    if 'internally share' in t and (not xs):
        xs.append(['internal_personnel_of', ['receiving_party']])
    if not xs and 'representatives' in t:
        xs.append(['representatives_of', ['receiving_party']])
    if not xs and any_phrase(t, ['third parties', 'third party']):
        xs.append(['third_parties'])
    return xs

def make_exceptions(t, perm):
    es = []
    if any_phrase(t, ['prior written consent', 'prior, written consent', 'prior written approval', 'prior written permission', 'expressly authorized in writing', 'express permission']):
        es.append(['authorization_exception', 'source-stated written authorization'])
    if any_phrase(t, ['required to analyze', 'required to fulfil', 'required to fulfill']):
        es.append(['purpose_exception', 'source-stated required activity'])
    if any_phrase(t, ['except as expressly permitted under', 'except as permitted under', 'except as provided in', 'except as provided under']):
        es.append(['cross_reference_exception', 'source-stated disclosure cross-reference'])
    if perm is not None:
        es.append(['permission_exception', perm])
    if not es:
        return ['no_exceptions']
    v = ['exception_set', es[0]]
    i = 1
    while i < len(es):
        v = ['add_exception', v, es[i]]
        i += 1
    return v

def parse_context(raw, ids, out, refs):
    t = raw.casefold()
    if not t:
        return
    if ('“representative” means' in t or '"representative" means' in t or 'representative means' in t) and any_phrase(t, ['employee', 'director', 'officer', 'agent', 'accountant', 'attorney', 'contractor']):
        cats = recipient_terms(t)
        fixed = []
        for c in cats:
            if len(c) > 1:
                c[1] = ['party']
            fixed.append(c)
        if fixed:
            add_statement(out, ['define_representative', ['party'], make_union(fixed)], ids)
    if any_phrase(t, ['information about employees', 'employee lists and records', 'human resources data']) and 'confidential' in t:
        add_statement(out, ['confidential_information_includes', ['employee_information', ['disclosing_party']]], ids)
    if 'whereas' in t and 'may' in t and ('disclos' in t) and ('confidential information' in t):
        add_statement(out, ['possible_disclosure_description', ['disclosing_party'], ['confidential_information'], ['receiving_party']], ids)
    if 'confidential information' not in t and 'such information' not in t and ('the same' not in t):
        return
    actor = ['named_recipient', 'Volunteer'] if 'volunteer agrees' in t else ['receiving_party']
    if 'neither it nor its representatives' in t and any_phrase(t, ['any other person', 'any other organization', 'other person or organization']):
        group = ['participant_union', ['receiving_party'], ['representatives_of', ['receiving_party']]]
        ex = make_exceptions(t, None)
        add_statement(out, ['prohibition', group, ['disclose', ['confidential_information'], ['outsiders_to', group]], ['no_condition'], ex], ids)
        return
    pmark = any_phrase(t, ['may disclose', 'may share', 'internally share', 'restrict access']) or ('not to disclose' in t and ' except ' in t)
    perm = None
    if pmark:
        seg = permission_segment(t)
        cats = recipient_terms(seg)
        if cats:
            perm = ['permission', actor, ['disclose', ['confidential_information'], make_union(cats)], make_condition(t)]
            add_statement(out, perm, ids)
    third = any_phrase(t, ['third parties', 'third party'])
    neg = any_phrase(t, ['shall not disclose', 'not to disclose', 'not to, without', 'not to, directly', 'not disclose, allow access', 'not to divulge'])
    if third and neg:
        ex = make_exceptions(t, perm)
        add_statement(out, ['prohibition', actor, ['disclose', ['confidential_information'], ['third_parties']], ['no_condition'], ex], ids)
        if any_phrase(t, ['except as expressly permitted under', 'except as permitted under', 'except as provided in', 'except as provided under']):
            add_once(refs, 'unresolved disclosure cross-reference')

def has_tag(term, name):
    todo = [term]
    while todo:
        x = todo.pop()
        if isinstance(x, list) and x:
            if x[0] == name:
                return True
            i = 1
            while i < len(x):
                if isinstance(x[i], list):
                    todo.append(x[i])
                i += 1
    return False

def apply(inputs,premises):
    old=_scope_previous_source(inputs,premises)
    extra=acquire_atoms({'source_text':inputs['source_text'],'source_spans':inputs['source_spans'],'source_output':old},premises)
    return {'statements':old['statements']+extra['statements'],
        'complete':old['complete'] and extra['complete'],
        'unresolved':old['unresolved']+extra['unresolved']}

def make_information_bundle(xs):
    if len(xs) == 1:
        return xs[0]
    v = xs[len(xs) - 1]
    i = len(xs) - 2
    while i >= 0:
        v = ['information_bundle', xs[i], v]
        i -= 1
    return v

def disposal_information(t):
    xs = [['confidential_information']]
    if 'copy' in t or 'copies' in t:
        xs.append(['copies_of', ['confidential_information']])
    if any_phrase(t, ['compilation', 'analysis', 'derivative work', 'notes or abstracts', 'notes and abstracts']):
        xs.append(['derivative_materials_of', ['confidential_information']])
    return make_information_bundle(xs)

def retention_information(t):
    xs = []
    if 'copy' in t or 'copies' in t or 'backup system' in t:
        xs.append(['copies_of', ['confidential_information']])
    if any_phrase(t, ['notes or abstracts', 'notes and abstracts', 'compilation', 'analysis', 'derivative work']):
        xs.append(['derivative_materials_of', ['confidential_information']])
    if not xs:
        xs.append(['confidential_information'])
    return make_information_bundle(xs)

def disposal_trigger(t):
    xs = []
    if 'termination of service' in t or 'service terminates' in t:
        xs.append(['service_termination'])
    elif any_phrase(t, ['upon termination of this agreement', 'upon termination of the agreement', 'termination of this agreement']):
        xs.append(['agreement_termination'])
    if 'completion of the purpose' in t:
        xs.append(['purpose_completion'])
    if 'upon' in t and 'request' in t or 'receipt of a written request' in t or 'written request from' in t or ('written request of' in t):
        xs.append(['request_by', ['disclosing_party']])
    if not xs:
        return None
    v = xs[0]
    i = 1
    while i < len(xs):
        v = ['trigger_alternative', v, xs[i]]
        i += 1
    return v

def retention_condition_for(t):
    if 'required' in t and 'applicable law' in t:
        return ['retention_condition', 'record copy required by applicable law']
    if 'archival purpose' in t:
        return ['retention_condition', 'one copy solely for archival purpose']
    if 'single copy' in t and any_phrase(t, ['regulatory compliance', 'compliance with the terms']):
        return ['retention_condition', 'single copy for regulatory and agreement compliance']
    if 'single copy' in t:
        return ['retention_condition', 'single copy for the source-stated purpose']
    return ['retention_condition', 'source-stated limited retention']

def parse_disposal(raw, ids, out):
    t = raw.casefold()
    if not t:
        return
    actor = ['named_recipient', 'Volunteer'] if 'volunteer' in t else ['receiving_party']
    explicit_retention = any_phrase(t, ['may retain', 'may maintain a single copy'])
    cond = retention_condition_for(t)
    if explicit_retention:
        add_statement(out, ['retention_permission', actor, retention_information(t), ['after_disposal'], cond], ids)
    if 'retained' in t and any_phrase(t, ['no copies', 'no copy', 'no copies, electronic or otherwise']):
        add_statement(out, ['retention_prohibition', actor, retention_information(t), ['after_disposal']], ids)
    trigger = disposal_trigger(t)
    if trigger is None:
        return
    do_return = re.search('\\breturn(?:ed|ing)?\\b', t, re.I) is not None
    do_destroy = re.search('\\bdestroy(?:ed|ing)?\\b', t, re.I) is not None and 'not destroyed' not in t
    if not do_return and (not do_destroy):
        return
    info = disposal_information(t)
    if do_return and do_destroy:
        action = ['action_alternative', ['return_to', info, ['disclosing_party']], ['destroy', info]]
    elif do_return:
        action = ['return_to', info, ['disclosing_party']]
    else:
        action = ['destroy', info]
    es = []
    if 'unless otherwise instructed in writing' in t:
        es.append(['authorization_exception', 'different written instructions from the disclosing participant'])
    if explicit_retention:
        es.append(['retention_exception', actor, retention_information(t), cond])
    if not es:
        exceptions = ['no_exceptions']
    else:
        exceptions = ['exception_set', es[0]]
        i = 1
        while i < len(es):
            exceptions = ['add_exception', exceptions, es[i]]
            i += 1
    add_statement(out, ['disposal_obligation', actor, action, trigger, exceptions], ids)

def low(value):
    if not isinstance(value, str):
        value = str(value)
    return value.casefold().strip()

def has_any(text, phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False

def unique(values):
    out = []
    for value in values:
        if value not in out:
            out.append(value)
    return out

def make_and(items):
    if not items:
        return ['no_condition']
    value = items[0]
    i = 1
    while i < len(items):
        value = ['and_condition', value, items[i]]
        i += 1
    return value

def owner_for_definition(term):
    if isinstance(term, list) and len(term) > 1:
        term[1] = ['party']
    return term

def recipient_items(text, owner):
    items = []
    if has_any(text, ['employee', 'staff', 'personnel']):
        items.append(['employees_of', owner])
    if 'director' in text:
        items.append(['directors_of', owner])
    if has_any(text, ['officer', 'official']):
        items.append(['officers_of', owner])
    if has_any(text, ['legal adviser', 'legal advisor', 'attorney', 'legal counsel']):
        items.append(['legal_advisors_of', owner])
    if has_any(text, ['financial adviser', 'financial advisor']):
        items.append(['financial_advisors_of', owner])
    if has_any(text, ['professional adviser', 'professional advisor']):
        items.append(['professional_advisors_of', owner])
    if 'accountant' in text:
        items.append(['accountants_of', owner])
    if 'consultant' in text:
        items.append(['consultants_of', owner])
    if 'contractor' in text:
        items.append(['independent_contractors_of', owner])
    if 'agent' in text:
        items.append(['agents_of', owner])
    if has_any(text, ['lender', 'finance provider']):
        items.append(['lenders_of', owner])
    if not items and 'representative' in text:
        items.append(['representatives_of', owner])
    return items

def disclosure_condition(text, raw):
    conditions = []
    if has_any(text, ['need to know', 'need-to-know', 'strict need to know', 'bona fide need']):
        conditions.append(['need_to_know', raw])
    if has_any(text, ['extent necessary', 'extent absolutely necessary', 'reasonably necessary', 'disclosure is necessary', 'knowledge of the confidential information is reasonably necessary']):
        conditions.append(['extent_necessary', raw])
    if has_any(text, ['written confidentiality agreement', 'written agreement with', 'signed the mandatory non-disclosure agreement', 'signed the mandatory nondisclosure agreement', 'bound to a duty of confidentiality', 'bound by obligations of confidentiality', 'treat the confidential information as confidential', 'advise such employees', 'complies with all the provisions of this agreement', 'obligated to protect']):
        conditions.append(['confidentiality_bound', raw])
    return make_and(conditions)

def actor_for(text):
    if 'volunteer' in text:
        return ['named_recipient', 'Volunteer']
    if 'auditor' in text and 'receiving party' not in text:
        return ['named_recipient', 'Auditor']
    return ['receiving_party']

def parse_definition(raw, uid, statements):
    text = low(raw)
    if not has_any(text, ['representative” means', 'representatives” means', '"representative" means', '"representatives" means']):
        return
    items = recipient_items(text, ['party'])
    if items:
        add_statement(statements, ['define_representative', ['party'], make_union(items)], [uid])

def parse_disclosure(raw, support, statements):
    text = low(raw)
    if not operative_information(text):
        return
    actor = actor_for(text)
    if permission_marker(text):
        items = recipient_items(text, ['receiving_party'])
        if items:
            permission = ['permission', actor, ['disclose', ['confidential_information'], make_union(items)], disclosure_condition(text, raw)]
            add_statement(statements, permission, support)
    if prohibition_marker(text) and has_any(text, ['third party', 'third parties', 'any other person', 'any other organization']):
        exceptions = []
        if has_any(text, ['prior written consent', 'prior written agreement', 'prior written approval', 'expressly authorized in writing']):
            exceptions.append(['authorization_exception', 'source-stated written authorization'])
        if has_any(text, ['required to analyze', 'required to fulfil', 'required to fulfill', 'required in the course of service']):
            exceptions.append(['purpose_exception', 'source-stated required activity'])
        if exceptions:
            ex = ['exception_set', exceptions[0]]
            i = 1
            while i < len(exceptions):
                ex = ['add_exception', ex, exceptions[i]]
                i += 1
        else:
            ex = ['no_exceptions']
        add_statement(statements, ['prohibition', actor, ['disclose', ['confidential_information'], ['third_parties']], ['no_condition'], ex], support)
    if has_any(text, ['neither it nor its representatives', 'neither the receiving party nor its representatives']) and has_any(text, ['any other person', 'any other organization']):
        group = ['participant_union', ['receiving_party'], ['representatives_of', ['receiving_party']]]
        add_statement(statements, ['prohibition', group, ['disclose', ['confidential_information'], ['outsiders_to', group]], ['no_condition'], ['no_exceptions']], support)

def information_scope(text):
    items = [['confidential_information']]
    if has_any(text, ['copy', 'copies', 'reproduction', 'record copy', 'backup', 'archive']):
        items.append(['copies_of', ['confidential_information']])
    if has_any(text, ['note', 'abstract', 'extract', 'analysis', 'study', 'summary', 'derivative']):
        items.append(['derivative_materials_of', ['confidential_information']])
    value = items[len(items) - 1]
    i = len(items) - 2
    while i >= 0:
        value = ['information_bundle', items[i], value]
        i -= 1
    return value

def trigger_terms(text):
    triggers = []
    if has_any(text, ['business relationship is not entered', 'relationship is not entered', 'fail to enter into a business relationship']):
        triggers.append(['relationship_nonformation_deadline'])
    if has_any(text, ['termination of service', 'service terminates', 'service with']):
        triggers.append(['service_termination'])
    if has_any(text, ['termination/expiration of the business relation', 'termination or expiration of the business relation', 'termination of the business relationship', 'termination of the working relationship']):
        triggers.append(['relationship_termination'])
    if has_any(text, ['termination of this agreement', 'expiration of this agreement', 'expiration or termination of this agreement', 'termination/expiration of this non-disclosure agreement']):
        triggers.append(['agreement_termination'])
    if 'completion of the purpose' in text:
        triggers.append(['purpose_completion'])
    if has_any(text, ['upon request', 'at any time upon request', 'promptly upon request', 'request by', 'request of', 'request from']):
        triggers.append(['request_by', ['disclosing_party']])
    return unique(triggers)

def trigger_value(triggers):
    if not triggers:
        return None
    value = triggers[0]
    i = 1
    while i < len(triggers):
        value = ['trigger_alternative', value, triggers[i]]
        i += 1
    return value

def add_disposal(raw, support, statements):
    text = low(raw)
    triggers = trigger_terms(text)
    if not triggers:
        return
    do_return = has_return_action(text)
    do_destroy = has_destroy_action(text)
    if not do_return and (not do_destroy):
        return
    info = information_scope(text)
    if do_return and do_destroy:
        action = ['action_alternative', ['return_to', info, ['disclosing_party']], ['destroy', info]]
    elif do_return:
        action = ['return_to', info, ['disclosing_party']]
    else:
        action = ['destroy', info]
    add_statement(statements, ['disposal_obligation', actor_for(text), action, trigger_value(triggers), ['no_exceptions']], support)

def add_retention(raw, uid, statements):
    text = low(raw)
    info = information_scope(text)
    actor = actor_for(text)
    if has_any(text, ['entitled to retain', 'may retain', 'may maintain a single copy', 'permitted to retain']):
        add_statement(statements, ['retention_permission', actor, info, ['after_disposal'], ['retention_condition', raw]], [uid])
    if has_any(text, ['without retaining any copies', 'no copies, electronic or otherwise', 'no copies or records thereof shall be retained', 'no copy shall be retained']):
        add_statement(statements, ['retention_prohibition', actor, info, ['after_disposal']], [uid])
    if has_any(text, ['not to make or retain copy', 'shall not retain any copy', 'must not retain any copy', 'no copies, electronic or otherwise, notes or abstracts of the foregoing shall be retained']):
        add_statement(statements, ['absolute_retention_prohibition', actor, info], [uid])

def term_has(term, name):
    todo = [term]
    while todo:
        item = todo.pop()
        if isinstance(item, list) and item:
            if item[0] == name:
                return True
            i = 1
            while i < len(item):
                if isinstance(item[i], list):
                    todo.append(item[i])
                i += 1
    return False

def _scope_previous_source(inputs, premises):
    spans = inputs.get('source_spans', [])
    statements = []
    source_output = inputs.get('source_output', {})
    if isinstance(source_output, dict):
        for row in source_output.get('statements', []):
            if isinstance(row, dict) and isinstance(row.get('term'), list):
                add_statement(statements, row.get('term'), row.get('support_ids', []))
    texts = []
    ids = []
    for span in spans:
        uid = span.get('id')
        raw = span.get('text', '')
        if not isinstance(raw, str):
            raw = str(raw)
        ids.append(uid)
        texts.append(raw)
        parse_definition(raw, uid, statements)
        parse_disclosure(raw, [uid], statements)
        add_disposal(raw, [uid], statements)
        add_retention(raw, uid, statements)
    i = 0
    while i < len(texts):
        current = low(texts[i])
        if current.endswith(':') and has_any(current, ['may disclose', 'do not apply to the disclosure', 'shall be handled as follows']) or (has_any(current, ['return of confidential information', 'shall be returned', 'returned to']) and (not trigger_terms(current))):
            j = i + 1
            while j < len(texts) and j <= i + 4:
                combined = ' '.join(texts[i:j + 1])
                support = ids[i:j + 1]
                parse_disclosure(combined, support, statements)
                add_disposal(combined, support, statements)
                j += 1
        triggers = trigger_terms(current)
        if triggers and (not has_return_action(current)) and (not has_destroy_action(current)):
            floor = max(0, i - 3)
            j = i - 1
            while j >= floor:
                previous = low(texts[j])
                if has_return_action(previous) or has_destroy_action(previous):
                    add_disposal(texts[j] + ' ' + texts[i], [ids[j], ids[i]], statements)
                    break
                j -= 1
        i += 1
    definitions = False
    unresolved = []
    for row in statements:
        if isinstance(row.get('term'), list) and row.get('term') and (row.get('term')[0] == 'define_representative'):
            definitions = True
    if not definitions:
        for row in statements:
            term = row.get('term')
            if term_has(term, 'representatives_of'):
                unresolved.append('Representatives membership is used by an operative rule but is not defined in the current source output.')
                break
    return {'statements': statements, 'complete': len(unresolved) == 0, 'unresolved': unresolved}

def atoms_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def atoms_add(out,term,support_ids):
    support=atoms_unique(support_ids)
    for row in out:
        if row.get('term')==term and row.get('support_ids',[])==support:
            return
    out.append({'term':term,'support_ids':support})

def atoms_parent_label(label):
    if not isinstance(label,str) or '.' not in label:
        return ''
    return label.rsplit('.',1)[0]

def atoms_trigger_kinds(raw):
    text=raw.casefold()
    kinds=[]
    if has_any(text,['upon demand','upon request','promptly upon request','at any time upon request','so requests','request in writing','written request','request of','request by','request from']):
        kinds.append('request')
    if has_any(text,['termination of this agreement','expiration of this agreement','termination or expiration of this agreement','expiration or other termination of this agreement']):
        kinds.append('agreement_end')
    if has_any(text,['termination of the project','expiration of the project','expiration or other termination of the project']):
        kinds.append('project_end')
    if has_any(text,['termination of the business relationship','termination/expiration of the business relation','termination of the working relationship']):
        kinds.append('relationship_end')
    if has_any(text,['termination of service','service terminates']):
        kinds.append('service_end')
    if has_any(text,['business relationship is not entered','relationship is not entered','fail to enter into a business relationship']):
        kinds.append('relationship_nonformation')
    kinds=atoms_unique(kinds)
    if len(kinds)>1:
        return ['multiple_explicit']
    return kinds

def atoms_scope_for(segments,index,kind):
    segment=segments[index]
    raw=segment.get('text','')
    text=raw.casefold()
    label=segment.get('label','')
    if kind=='disposal' and atoms_trigger_kinds(raw):
        return label
    if kind=='disclosure' and has_any(text,['may disclose','may be disclosed','only to disclose','restrict access','restrict disclosure','except in confidence']):
        return label
    parent=segment.get('parent','')
    while parent:
        j=index-1
        while j>=0:
            previous=segments[j]
            if previous.get('label')==parent:
                ptext=previous.get('text','').casefold()
                if kind=='disposal' and (atoms_trigger_kinds(previous.get('text','')) or has_any(ptext,['shall immediately','return','destroy','delete','erase'])):
                    return parent
                if kind=='disclosure' and has_any(ptext,['may disclose','may be disclosed','permitted disclosure','restrict access','restrict disclosure']):
                    return parent
            j-=1
        parent=atoms_parent_label(parent)
    return label

def atoms_action_parts(raw):
    text=raw.casefold()
    returned=re.search(r'\breturn(?:ed|ing)?\b',text,re.I)
    destroyed=re.search(r'\b(?:destroy|delete|erase)(?:d|ing)?\b',text,re.I)
    out=[]
    if returned is not None and destroyed is not None:
        if returned.start()<destroyed.start():
            out.append(('return',raw[returned.start():destroyed.start()].strip()))
            out.append(('destroy',raw[destroyed.start():].strip()))
        else:
            out.append(('destroy',raw[destroyed.start():returned.start()].strip()))
            out.append(('return',raw[returned.start():].strip()))
    elif returned is not None:
        out.append(('return',raw[returned.start():].strip()))
    elif destroyed is not None:
        out.append(('destroy',raw[destroyed.start():].strip()))
    return out

def atoms_material(action_kind,raw):
    text=raw.casefold()
    copies=has_any(text,['copy','copies','reproduction','reproductions'])
    information=has_any(text,['confidential information','such confidential information','all information','such information'])
    derivatives=has_any(text,['notes','abstracts','analyses','analysis','extracts','derivative'])
    all_materials=has_any(text,['any and all materials','all materials','all documents, files'])
    if all_materials:
        kind='all_source_materials'
    elif information and copies and derivatives:
        kind='information_copies_and_derivatives'
    elif information and copies:
        kind='confidential_information_and_copies'
    elif copies and not information:
        kind='copies_only'
    elif information:
        kind='confidential_information_only'
    else:
        kind='unresolved_material'
    if has_any(text,['anyone to whom','such copies and any further copies','copies made by them']):
        owner='receiving_and_downstream_copies'
    elif has_any(text,['copies made by the receiving party','copies made by recipient']):
        owner='receiving_party_copies'
    elif copies:
        owner='all_source_copies'
    elif all_materials:
        owner='source_bounded_materials'
    else:
        owner='not_applicable'
    return (kind,owner)

def atoms_emit_disposal(segments,out,unresolved):
    actions=[]
    scopes={}
    i=0
    while i<len(segments):
        segment=segments[i]
        raw=segment.get('text','')
        text=raw.casefold()
        parts=atoms_action_parts(raw)
        relevant=bool(parts) or bool(atoms_trigger_kinds(raw))
        if relevant and has_any(text,['confidential information','such information','copies','copy','materials','documents','return','destroy','delete','erase','shall immediately']):
            scope=atoms_scope_for(segments,i,'disposal')
            atoms_add(out,['source_clause_atom',scope,segment.get('label',''),segment.get('parent',''),'disposal',raw],[segment.get('unit')])
            data=scopes.get(scope,{'units':[],'texts':[],'actions':[],'triggers':[]})
            data['units']=atoms_unique(data['units']+[segment.get('unit')])
            data['texts'].append(raw)
            for trigger_kind in atoms_trigger_kinds(raw):
                trigger=['source_disposal_trigger_atom',scope,trigger_kind,raw]
                atoms_add(out,trigger,[segment.get('unit')])
                data['triggers'].append((trigger_kind,raw,segment.get('unit')))
            for action_kind,action_raw in parts:
                key=segment.get('label','')+':'+action_kind
                material_kind,owner_kind=atoms_material(action_kind,action_raw)
                atoms_add(out,['source_disposal_action_atom',scope,key,segment.get('label',''),action_kind,action_raw],[segment.get('unit')])
                atoms_add(out,['source_disposal_material_atom',scope,key,material_kind,owner_kind,action_raw],[segment.get('unit')])
                if material_kind=='unresolved_material':
                    unresolved.append('Unresolved '+action_kind+' material in source clause '+segment.get('label',''))
                if action_kind=='destroy' and has_any(text,['confirm to','certify the destruction','confirmation of destruction']):
                    atoms_add(out,['source_disposal_qualifier_atom',scope,key,'destruction_confirmation',raw],[segment.get('unit')])
                data['actions'].append({'key':key,'kind':action_kind,'raw':action_raw,'unit':segment.get('unit'),'label':segment.get('label','')})
            scopes[scope]=data
        i+=1
    for scope,data in scopes.items():
        returns=[]
        destroys=[]
        for action in data['actions']:
            if action.get('kind')=='return':
                returns.append(action)
            if action.get('kind')=='destroy':
                destroys.append(action)
        combined=' '.join(data['texts'])
        lower=combined.casefold()
        connector_ok=False
        if returns and destroys:
            left=returns[0]
            right=destroys[0]
            if has_any(lower,['expressly authorised in writing','expressly authorized in writing','where authorised in writing','where authorized in writing']):
                connector='authorized_alternative'
                atoms_add(out,['source_disposal_qualifier_atom',scope,right.get('key'),'written_authorization',combined],data['units'])
            elif '; and' in lower or ' and  ' in lower or re.search(r'\band\s+[0-9]+(?:\.[0-9]+)+\s+(?:destroy|delete|erase)',lower,re.I) is not None:
                connector='and'
            elif ' or ' in lower:
                connector='or'
            else:
                connector='unresolved_connector'
                unresolved.append('Unresolved return/destroy connector in source scope '+scope)
            atoms_add(out,['source_disposal_connector_atom',scope,left.get('key'),right.get('key'),connector,combined],data['units'])
            connector_ok=connector!='unresolved_connector'
        elif returns:
            action=returns[0]
            atoms_add(out,['source_disposal_connector_atom',scope,action.get('key'),action.get('key'),'single_return',combined],data['units'])
            connector_ok=True
        elif destroys:
            action=destroys[0]
            atoms_add(out,['source_disposal_connector_atom',scope,action.get('key'),action.get('key'),'single_destroy',combined],data['units'])
            connector_ok=True
        materials_ok=True
        for action in data['actions']:
            material_kind,owner_kind=atoms_material(action.get('kind'),action.get('raw'))
            if material_kind=='unresolved_material':
                materials_ok=False
        if data['actions'] and data['triggers'] and connector_ok and materials_ok:
            atoms_add(out,['source_program_scope_supported',scope],data['units'])
        elif data['actions'] and not data['triggers']:
            unresolved.append('No explicit trigger found for disposal scope '+scope)

def atoms_emit_disclosure(segments,out,unresolved):
    i=0
    while i<len(segments):
        segment=segments[i]
        raw=segment.get('text','')
        text=raw.casefold()
        scope=atoms_scope_for(segments,i,'disclosure')
        parent_permission=False
        j=i-1
        while j>=0:
            if segments[j].get('label')==segment.get('parent') and has_any(segments[j].get('text','').casefold(),['may disclose','may be disclosed','permitted disclosure']):
                parent_permission=True
                break
            j-=1
        direct=has_any(text,['may disclose','may be disclosed','only to disclose','disclosed only to','restrict access','restrict disclosure','except in confidence'])
        child_permission=parent_permission and has_any(text,['only to such','only to employees','only to its employees'])
        roles=[]
        if 'employee' in text or 'staff' in text or 'personnel' in text:
            owner='controlled_entity' if has_any(text,['companies directly or indirectly owned or controlled','company controlled by','under common control']) else 'receiving_party'
            roles.append(('employee',owner))
        if 'contractor' in text:
            roles.append(('contractor','receiving_party'))
        if 'consultant' in text:
            roles.append(('consultant','receiving_party'))
        if 'agent' in text:
            roles.append(('agent','receiving_party'))
        if 'adviser' in text or 'advisor' in text:
            roles.append(('professional_adviser','receiving_party'))
        roles=atoms_unique(roles)
        if (direct or child_permission) and roles:
            atoms_add(out,['source_clause_atom',scope,segment.get('label',''),segment.get('parent',''),'disclosure_permission',raw],[segment.get('unit')])
            atoms_add(out,['source_disclosure_permission_atom',scope,segment.get('label',''),raw],[segment.get('unit')])
            for role,owner in roles:
                atoms_add(out,['source_disclosure_recipient_atom',scope,segment.get('label',''),role,owner,raw],[segment.get('unit')])
            if has_any(text,['need to know','need-to-know','bona fide need']):
                atoms_add(out,['source_disclosure_condition_atom',scope,segment.get('label',''),'need_to_know',raw],[segment.get('unit')])
            if has_any(text,['strictly necessary','extent necessary','extent absolutely necessary','disclosure is necessary','reasonably necessary']):
                atoms_add(out,['source_disclosure_condition_atom',scope,segment.get('label',''),'extent_necessary',raw],[segment.get('unit')])
            if has_any(text,['subject to the provisions','bound by obligations of confidentiality','treat the confidential information as confidential','obligated to protect']):
                atoms_add(out,['source_disclosure_condition_atom',scope,segment.get('label',''),'confidentiality_bound',raw],[segment.get('unit')])
            if has_any(text,['written confidentiality agreement','written confidentiality agreements','written non-disclosure agreement','written nondisclosure agreement']):
                atoms_add(out,['source_disclosure_condition_atom',scope,segment.get('label',''),'written_confidentiality',raw],[segment.get('unit')])
        prohibited=has_any(text,['shall not disclose','not to disclose','not disclose it to anyone','not disclose the confidential information to any third party'])
        if prohibited and has_any(text,['anyone','third party','third parties']):
            cross=has_any(text,['unless this agreement expressly permits','except as expressly permitted','except as permitted under','except as provided under'])
            authorization=has_any(text,['prior written consent','express, prior written consent','prior written approval'])
            if cross and authorization:
                exception_kind='cross_reference_and_authorization'
            elif cross:
                exception_kind='unresolved_cross_reference'
            elif authorization:
                exception_kind='authorization'
            else:
                exception_kind='none'
            atoms_add(out,['source_clause_atom',scope,segment.get('label',''),segment.get('parent',''),'disclosure_prohibition',raw],[segment.get('unit')])
            atoms_add(out,['source_disclosure_prohibition_atom',scope,segment.get('label',''),exception_kind,raw],[segment.get('unit')])
            if cross:
                atoms_add(out,['source_reference_atom',scope,segment.get('label',''),'disclosure_permission_cross_reference',raw],[segment.get('unit')])
                unresolved.append('Disclosure permission cross-reference remains unresolved in clause '+segment.get('label',''))
        i+=1

def acquire_atoms(inputs,premises):
    spans=[]
    for span in inputs.get('source_spans',[]):
        if isinstance(span,dict):
            spans.append(span)
    statements=[]
    unresolved=[]
    segments=atoms_segments(spans)
    atoms_emit_disclosure(segments,statements,unresolved)
    atoms_emit_disposal(segments,statements,unresolved)
    return {'statements':statements,'complete':len(atoms_unique(unresolved))==0,'unresolved':atoms_unique(unresolved)}
